import re

from moler.exceptions import ParsingDone, CommandFailure
from ta_moler.cmd.rtg.ws.genericrtgws import GenericRtgWs

__author__ = 'Dawid Gwizdz, Marek Zajac'
__copyright__ = 'Copyright (C) 2020, Nokia'
__email__ = 'dawid.gwizdz@nokia.com, marek.zajac@nokia.com'


class GenerateTtiTrace(GenericRtgWs):
    """Command for execute generate tti trace script."""

    def __init__(self, connection, src, dst, path="/opt/rtg/lib/wireshark_adapter_to_ttitrace/generate_tti_trace.py",
                 options=None, prompt=None, newline_chars=None, runner=None):
        """
        Generate tti trace command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param src: Path to directory with pcaps.
        :param dst: Path to target directory for tti trace.
        :param path: Path to generate_tti_trace.py file.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenerateTtiTrace, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.src = src
        self.dst = dst
        self.path = path
        self.options = options

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"python {self.path} {self.src} {self.dst}"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_done(line)
            except ParsingDone:
                pass
        return super(GenerateTtiTrace, self).on_new_line(line, is_full_line)

    # Example line: Got it done comrade!
    _re_done = re.compile(r'Got it done comrade!')

    def _parse_done(self, line):
        """
        Parse line containing done message.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_done, line):
            self.set_result({})
            raise ParsingDone

    # Example line:
    # IOError: [Errno 13] Permission denied: '/home/ute/nbiot_robot/LTE4898/ttitrace/Refactored_Converted_pcap000.csv'
    _re_error = re.compile(r'Error:|error:')

    def _parse_error(self, line):
        """
        Parse line containing error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.search(self._re_error, line)))
            raise ParsingDone


